//! Minimal re-implementation of the pieces of the C++ `indicators` library
//! used by test7: `ProgressDisplay` and `Percentage`.

/// Displays progress as `Progress: X.X% (current/total)`.
pub struct ProgressDisplay {
    total: i64,
    current: i64,
}

impl ProgressDisplay {
    pub fn new(total: i64) -> Self {
        ProgressDisplay { total, current: 0 }
    }

    /// Set the current progress value (no clamping, mirroring the C++ API).
    pub fn update(&mut self, current: i64) {
        self.current = current;
    }

    /// Add to the current progress value.
    pub fn increment(&mut self, amount: i64) {
        self.current += amount;
    }

    /// Render the display string, e.g. `Progress: 75.0% (150/200)`.
    pub fn display(&self) -> String {
        let percent = if self.total != 0 {
            self.current as f64 / self.total as f64 * 100.0
        } else {
            0.0
        };
        format!(
            "Progress: {:.1}% ({}/{})",
            percent, self.current, self.total
        )
    }
}

/// A percentage value rendered with a fixed number of decimal places,
/// e.g. `Percentage::new(0.35, 2).str()` -> `"35.00%"`.
pub struct Percentage {
    value: f32,
    precision: usize,
}

impl Percentage {
    pub fn new(value: f32, precision: usize) -> Self {
        Percentage { value, precision }
    }

    pub fn str(&self) -> String {
        format!(
            "{:.prec$}%",
            self.value as f64 * 100.0,
            prec = self.precision
        )
    }
}

