mod indicators;

use indicators::{Percentage, ProgressDisplay};

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let progress: i64 = if args.len() > 1 {
        // Mirrors std::stoi: panics (aborts) on invalid input.
        args[1]
            .trim()
            .parse()
            .expect("stoi")
    } else {
        150
    };

    let mut display = ProgressDisplay::new(200);
    display.update(progress);
    println!("{}", display.display());

    display.increment(25);
    println!("{}", display.display());

    let pct1 = Percentage::new(0.15, 1);
    let pct2 = Percentage::new(0.35, 2);
    let pct3 = Percentage::new(0.65, 3);
    println!("{}", pct1.str());
    println!("{}", pct2.str());
    println!("{}", pct3.str());
}

